const SOL5 = '';
const SOL6 = '';
const VAL5 = '';
const VAL6 = '';

function taglia(blob: string, n: number): string[] {
  const out: string[] = [];
  for (let i = 0; i < blob.length; i += n) out.push(blob.slice(i, i + n));
  return out;
}

export const SOLUZIONI_EN: Record<LunghezzaParola, string[]> = {
  5: taglia(SOL5, 5),
  6: taglia(SOL6, 6),
};

